245	    /**
246	     * The owner's salutation, derived on read: the {@code title} and {@code lastName} separated
247	     * by a single space (e.g. {@code 'DR Franklin'}) when a title is present, or just the
248	     * {@code lastName} when no title is set.
249	     *
250	     * @return the salutation
251	     */
252	    @Transient
253	    public String getSalutation() {
254	        if (this.title != null && !this.title.isBlank()) {
255	            return this.title + " " + getLastName();
256	        }
257	        return getLastName();
258	    }
259	
260	    /**
261	     * The owner's membership points, derived on read from the fields assigned at create. Points
262	     * start at 0 and accumulate: 2 when an email is present, 1 when {@code namesakeCount} is 0,
263	     * 2 when the household has 3 or more members ({@code householdMemberCount} of 3 or more), and
264	     * 3 when the owner's tenure exceeds 365 days. Tenure is the number of whole days between the
265	     * {@code registrationDate} and the current date. Because a newly created owner has zero tenure,
266	     * the tenure points are only earned once the owner's tenure passes 365 days.
267	     *
268	     * @return the membership points, 0 or more
269	     */
270	    @Transient
271	    public Integer getMembershipPoints() {
272	        int points = 0;
273	        if (this.email != null && !this.email.isBlank()) {
274	            points += 2;
275	        }
276	        if (this.namesakeCount != null && this.namesakeCount == 0) {
277	            points += 1;
278	        }
279	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
280	            points += 2;
281	        }
282	        if (this.registrationDate != null
283	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
284	            points += 3;
285	        }
286	        return points;
287	    }
288	
289	    /**
290	     * The owner's numeric membership level, derived on read by mapping {@link #getMembershipPoints}
291	     * to a level: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
292	     * Because a newly created owner has zero tenure, level 4 (which requires the tenure points) is
293	     * reached only once the owner's tenure passes 365 days.
294	     *
295	     * @return the membership level, from 1 to 4
296	     */
297	    @Transient
298	    public Integer getMembershipLevel() {
299	        int points = getMembershipPoints();
300	        if (points >= 6) {
301	            return 4;
302	        }
303	        if (points >= 4) {
304	            return 3;
305	        }
306	        if (points >= 2) {
307	            return 2;
308	        }
309	        return 1;
310	    }
311	
312	    /**
313	     * The owner's preferred contact channel, derived on read: {@code 'EMAIL'} when an
314	     * email address is present, otherwise {@code 'PHONE'}.
315	     *
316	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
317	     */
318	    @Transient
319	    public String getContactPreference() {
320	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
321	    }
322	
323	    /**
324	     * The owner's age band, derived on read from {@code birthDate} against the
325	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18, {@code 'ADULT'}
326	     * from 18 to 64, and {@code 'SENIOR'} at 65 or older. The age is the number of whole years
327	     * between the birth date and the registration date (falling back to the current date when no
328	     * registration date is set).
329	     *
330	     * @return the age band, or {@code null} when no {@code birthDate} is set
331	     */
332	    @Transient
333	    public String getAgeBand() {
334	        if (this.birthDate == null) {
335	            return null;
336	        }
337	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
338	        int age = Period.between(this.birthDate, reference).getYears();
339	        if (age < 18) {
340	            return "MINOR";
341	        }
342	        if (age < 65) {
343	            return "ADULT";
344	        }
345	        return "SENIOR";
346	    }
347	
348	    /**
349	     * The owner's check digit, derived on read: a single Luhn check digit computed over the
350	     * digits contained in the owner's {@code customerCode}.
351	     *
352	     * @return the Luhn check digit (0-9), or {@code null} when no customer code is assigned
353	     */
354	    @Transient
355	    public Integer getCheckDigit() {
356	        if (this.customerCode == null) {
357	            return null;
358	        }
359	        int sum = 0;
360	        boolean dbl = true;
361	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
362	            char c = this.customerCode.charAt(i);
363	            if (c < '0' || c > '9') {
364	                continue;
365	            }
366	            int d = c - '0';
367	            if (dbl) {
368	                d *= 2;
369	                if (d > 9) {
370	                    d -= 9;
371	                }
372	            }
373	            sum += d;
374	            dbl = !dbl;
375	        }
376	        return (10 - (sum % 10)) % 10;
377	    }
378	
379	    /**
380	     * The owner's stored E.164 {@code telephone} formatted for humans, derived on read: the
381	     * leading {@code '+'} and country code, a space, then the national digits grouped in threes
382	     * (e.g. {@code '+61 412 345 678'} for a stored {@code '+61412345678'}). The recognised
383	     * country codes are {@code '+61'} (Australia) and {@code '+1'} (NANP); any other prefix falls
384	     * back to a two-digit country code. The raw {@code telephone} is left in E.164 form.
385	     *
386	     * @return the human-formatted telephone, or the raw value when it is not in E.164 form
387	     */
388	    @Transient
389	    public String getTelephoneDisplay() {
390	        if (this.telephone == null || !this.telephone.startsWith("+")
391	                || !this.telephone.substring(1).matches("[0-9]+")) {
392	            return this.telephone;
393	        }
394	        String digits = this.telephone.substring(1);
395	        String countryCode;
396	        if (digits.startsWith("61")) {
397	            countryCode = "61";
398	        } else if (digits.startsWith("1")) {
399	            countryCode = "1";
400	        } else {
401	            countryCode = digits.length() > 2 ? digits.substring(0, 2) : digits;
402	        }
403	        String national = digits.substring(countryCode.length());
404	        StringBuilder display = new StringBuilder("+").append(countryCode);
405	        for (int i = 0; i < national.length(); i += 3) {
406	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
407	        }
408	        return display.toString();
409	    }
410	
411	    /**
412	     * The owner's derived duplicate-detection key: the single consolidated identity used to
413	     * detect duplicate owners on create. It is formed as
414	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} from the
415	     * owner's already-normalized {@code telephone} (E.164 form), its lower-cased {@code email}
416	     * (empty when absent) and its assigned {@code householdId}. Two owners are duplicates only
417	     * when their whole {@code identityKey} values are equal.
418	     *
419	     * @return the consolidated identity key
420	     */
421	    @Transient
422	    public String getIdentityKey() {
423	        String telephonePart = this.telephone == null ? "" : this.telephone;
424	        String emailPart = this.email == null ? "" : this.email;
425	        String householdPart = this.householdId == null ? "" : this.householdId;
426	        return telephonePart + "|" + emailPart + "|" + householdPart;
427	    }
428	
429	    protected Set<Pet> getPetsInternal() {
430	        if (this.pets == null) {
431	            this.pets = new HashSet<>();
432	        }
433	        return this.pets;
434	    }
435	
436	    protected void setPetsInternal(Set<Pet> pets) {
437	        this.pets = pets;
438	    }
439	
440	    public List<Pet> getPets() {
441	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
442	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
443	        return Collections.unmodifiableList(sortedPets);
444	    }
445	
446	    public void setPets(List<Pet> pets) {
447	        this.pets = new HashSet<>(pets);
448	    }
449	
450	    public void addPet(Pet pet) {
451	        getPetsInternal().add(pet);
452	        pet.setOwner(this);
453	    }
454	
455	    /**
456	     * Return the Pet with the given name, or null if none found for this Owner.
457	     *
458	     * @param name to test
459	     * @return true if pet name is already in use
460	     */
461	    public Pet getPet(String name) {
462	        return getPet(name, false);
463	    }
464	
465	    /**
466	     * Return the Pet with the given name, or null if none found for this Owner.
467	     *
468	     * @param name to test
469	     * @return true if pet name is already in use
470	     */
471	    public Pet getPet(String name, boolean ignoreNew) {
472	        name = name.toLowerCase();
473	        for (Pet pet : getPetsInternal()) {
474	            if (!ignoreNew || !pet.isNew()) {
475	                String compName = pet.getName();
476	                compName = compName.toLowerCase();
477	                if (compName.equals(name)) {
478	                    return pet;
479	                }
480	            }
481	        }
482	        return null;
483	    }
484	
485	    public Pet getPet(Integer petId) {
486	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
487	    }
488	
489	    @Override
490	    public String toString() {
491	        return new ToStringCreator(this)
492	
493	            .append("id", this.getId())
494	            .append("new", this.isNew())
495	            .append("lastName", this.getLastName())
496	            .append("firstName", this.getFirstName())
497	            .append("address", this.address)
498	            .append("city", this.city)
499	            .append("telephone", this.telephone)
500	            .append("email", this.email)
501	            .toString();
502	    }
503	}
