531	    /**
532	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
533	     * following Monday; any weekday is returned unchanged.
534	     *
535	     * @param date the date to adjust
536	     * @return the same date when it is a weekday, otherwise the next Monday
537	     */
538	    private static LocalDate toBusinessDay(LocalDate date) {
539	        return switch (date.getDayOfWeek()) {
540	            case SATURDAY -> date.plusDays(2);
541	            case SUNDAY -> date.plusDays(1);
542	            default -> date;
543	        };
544	    }
